
public class Triangle02 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		for (int i = 0; i < 6; i++) {
			int num = 1;
			
			for (int j = 0 ; j <= i; j++){
				if ( j <=i)
					System.out.print(num++ + " ");
			}
			System.out.println();	
		}	
	}

}
